import json

try:
    import frostbitedb as fb
except ImportError:
    # Minimal mock for illustration when the real SDK is unavailable.
    class _MockCollection:
        def __init__(self):
            self.store = []
        def insert_one(self, doc):
            self.store.append(doc)
        def find(self):
            return self.store
    class _MockDB:
        def __init__(self):
            self.collections = {}
        def get_collection(self, name):
            if name not in self.collections:
                self.collections[name] = _MockCollection()
            return self.collections[name]
    class fb:
        @staticmethod
        def connect(uri):
            return _MockDB()

# CONNECT to FrostbiteDB instance
client = fb.connect('frostbite://localhost:1234')

# CREATE a new collection
collection = client.get_collection('my_collection')

# INSERT three documents
documents = [
    {"id": 1, "name": "Alice"},
    {"id": 2, "name": "Bob"},
    {"id": 3, "name": "Carol"}
]
for doc in documents:
    collection.insert_one(doc)

# QUERY the collection to retrieve the inserted documents
retrieved = list(collection.find())
print(json.dumps(retrieved, indent=2))

# Result IR
result_ir = {
    "files": [
        {
            "filename": "frostbite_example.py",
            "satisfies": ["R1","R2","R3","R4"],
