                "path": "execution://body",
                "section": "code",
                "observed": "import frostbitedb as fb ...
client = fb.connect('frostbite://localhost:1234')
collection = client.get_collection('my_collection')
...
retrieved = list(collection.find())"
            }
        }
    ],
    "reconciliation": [
        {"requirement": "R1", "status": "satisfied", "evidence": {"path": "execution://body", "section": "code", "observed": "client = fb.connect('frostbite://localhost:1234')"}},
        {"requirement": "R2", "status": "satisfied", "evidence": {"path": "execution://body", "section": "code", "observed": "collection = client.get_collection('my_collection')"}},
        {"requirement": "R3", "status": "satisfied", "evidence": {"path": "execution://body", "section": "code", "observed": "for doc in documents:
    collection.insert_one(doc)"}},
        {"requirement": "R4", "status": "satisfied", "evidence": {"path": "execution://body", "section": "code", "observed": "retrieved = list(collection.find())"}}
    ],
    "open_defects": []
